package connect

import "errors"

// ResultOf computes the winner of a game of Hex / Polygon.
//
// The board is a parallelogram of hexagonal cells, represented as a slice of
// strings (one per row) with no spaces. Player "X" connects from the left side
// to the right side, while player "O" connects from the top side to the bottom
// side. It returns "X" or "O" for the winner, or an empty string when nobody
// has won yet.
func ResultOf(lines []string) (string, error) {
	if len(lines) == 0 {
		return "", nil
	}

	rows := len(lines)
	cols := len(lines[0])

	// Every row must have the same length to form a valid board.
	for _, line := range lines {
		if len(line) != cols {
			return "", errors.New("invalid board: rows have different lengths")
		}
	}

	// Check X first: a connection from the left edge to the right edge.
	if hasPath(lines, 'X', rows, cols, true) {
		return "X", nil
	}

	// Then check O: a connection from the top edge to the bottom edge.
	if hasPath(lines, 'O', rows, cols, false) {
		return "O", nil
	}

	return "", nil
}

// hasPath reports whether the stones of `player` form a connected path between
// the two opposite sides that player is assigned. For X (isX true) those sides
// are the left and right edges (columns 0 and cols-1); for O they are the top
// and bottom edges (rows 0 and rows-1).
func hasPath(lines []string, player rune, rows, cols int, isX bool) bool {
	// The six neighbours of a cell in the hexagonal (parallelogram) grid. A
	// cell at (r, c) is adjacent to:
	//   (r,   c-1) left
	//   (r,   c+1) right
	//   (r-1, c  ) up
	//   (r-1, c+1) up-right
	//   (r+1, c-1) down-left
	//   (r+1, c  ) down
	neighbors := [6][2]int{
		{0, -1}, {0, 1},
		{-1, 0}, {-1, 1},
		{1, -1}, {1, 0},
	}

	visited := make([][]bool, rows)
	for r := range visited {
		visited[r] = make([]bool, cols)
	}

	// Seed the search with every stone of `player` sitting on the starting
	// side.
	var stack [][2]int
	for r := 0; r < rows; r++ {
		for c := 0; c < cols; c++ {
			start := (isX && c == 0) || (!isX && r == 0)
			if start && lines[r][c] == player {
				visited[r][c] = true
				stack = append(stack, [2]int{r, c})
			}
		}
	}

	// Depth-first search over the connected stones.
	for len(stack) > 0 {
		cell := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		r, c := cell[0], cell[1]

		// Reached the opposite side?
		if (isX && c == cols-1) || (!isX && r == rows-1) {
			return true
		}

		for _, d := range neighbors {
			nr, nc := r+d[0], c+d[1]
			if nr < 0 || nr >= rows || nc < 0 || nc >= cols {
				continue
			}
			if visited[nr][nc] || lines[nr][nc] != player {
				continue
			}
			visited[nr][nc] = true
			stack = append(stack, [2]int{nr, nc})
		}
	}

	return false
}

